(@CHATTER_TEXTS_START+0,'hello|hi|hey|heya|hiya|howdy|greetings|good morning|good evening|good day|yo|sup|hail|well met',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+1,'bye|goodbye|good bye|bye bye|farewell|see you|see ya|cya|good night|take care|so long|cheerio',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+2,'Hello, %target!','Hi there, %target.','Well met, %target!','Greetings, %target.','Hey %target, how\'s it going?','Good to see you, %target.','Oh, hello there!','Hi! Nice weather in %zone today, isn\'t it?','-1'),
(@CHATTER_TEXTS_START+3,'Hey %target! Safe travels.','Hail, %target!','Hello, %target. Need a hand with anything?','Ah, another adventurer. Hello, %target!','Evening, %target. Or is it morning? I lose track out here.','Hi %target! Watch yourself out here.','May your blade stay sharp, %target.','Oh hey, %target! Fancy meeting you here in %zone.','-1'),
(@CHATTER_TEXTS_START+4,'Hello, %target!','Hi %target!','Hey! Good to see you, %target.','Greetings, %target. What brings you here?','Hi there! Anything I can do for you?','Well met, %target.','Oh, hi! Didn\'t see you there.','Hey %target, how are you?','-1'),
(@CHATTER_TEXTS_START+5,'Goodbye, %target!','See you around, %target.','Take care!','Farewell, %target. Safe travels.','Bye! Don\'t get eaten by anything.','Later, %target!','Until next time.','Good luck out there, %target.','-1'),
(@CHATTER_TEXTS_START+6,'Anyone up for some adventure in %zone?','Any group need backup? %class right here!','Level %level %class looking for company.','Boring...','Anybody doing something interesting?','Does anyone feel alone out here?','Maybe a duel somewhere in %zone?','Who wants to team up?','-1'),
(@CHATTER_TEXTS_START+7,'It\'s quiet in %zone today. Too quiet.','Could use a break. My feet are killing me.','Has anyone seen a decent inn around %zone?','I swear the monsters here get tougher every day.','Anyone know a good place to fish around here?','What a beautiful day in %zone.','Need a friend.','Note to self: buy more bandages.','-1'),
(@CHATTER_TEXTS_START+8,'Any other %race around? Let\'s stick together.','Offering my services as a %class. Payment in gold or cookies.','Where\'s the nearest flight master again?','Is it just me, or is %zone bigger than it looks on the map?','I could really go for a drink right now.','Anyone else hear that? No? Just me then.','Looking for a guild that doesn\'t take itself too seriously.','Every time I repair my gear, I get a little poorer.','-1'),
(@CHATTER_TEXTS_START+9,'%target down.','And another %target hits the ground.','%target is history.','Took care of %target.','%target bites the dust.','Easy. Next!','%target won\'t bother anyone anymore.','And stay down, %target.','-1'),
(@CHATTER_TEXTS_START+10,'Took down %target! That was intense.','%target was tough, but not tough enough.','Phew... %target is finally down.','Did anyone see that? I just beat %target!','%target, level %target_level. Not bad for level %level.','%target hit like a kodo. Still won though.','Elite, they said. Dangerous, they said. %target is down.','Need a moment to catch my breath after %target.','-1'),
(@CHATTER_TEXTS_START+11,'Found and killed %target! Rare spawn, baby!','Guess who just took down %target in %zone?','%target is down. Sorry rare hunters, maybe next time.','Finally got %target! Been looking for that one.','Rare kill: %target. Today is a good day.','%target won\'t be roaming %zone anymore.','Wow, %target! Didn\'t expect to run into that one.','Sorry, rare hunters: %target is mine.','-1'),
(@CHATTER_TEXTS_START+12,'%target has fallen!','We did it! %target is defeated!','%target is no more. Victory!','That\'s how it\'s done! Goodbye, %target.','%target down! Loot time!','Another boss bites the dust: %target.','Victory over %target! Songs will be sung.','%target thought we could be stopped. Wrong.','-1'),
(@CHATTER_TEXTS_START+13,'Nice try, %target.','%target, better luck next time.','Don\'t take it personally, %target.','That\'s what you get, %target!','Rest in peace, %target.','Get back up, %target, and try again.','Victory is mine!','Too slow, %target.','-1'),
(@CHATTER_TEXTS_START+14,'Ding!','Yes! I am level %level!','Level up! Now level %level!','Ding! Level %level reached!','Finally, level %level!','I feel stronger already. Level %level!','Level %level. The grind pays off.','Woohoo, level %level %class right here!','-1'),
(@CHATTER_TEXTS_START+15,'somewhere',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+16,'What\'s up, %target?','Hm? You need something, %target?','I hear you, %target.','Can\'t talk long, I\'m on my way somewhere in %zone.','Sure, sure. Whatever you say, %target.','Sorry %target, not sure what you mean.','Interesting. Tell me more some other time.','Ha! Good one, %target.','-1'),
(@CHATTER_TEXTS_START+17,'Busy fighting, talk later!','Not now, %target!','Kind of in the middle of something here!','Hold on, I\'m fighting!',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+18,'%zone at last.','So this is %zone. Looks nice enough.','Ah, %zone. It has been a while.','Welcome to %zone, %name. Try not to die.','%zone... I have heard stories about this place.','Finally out of there. Hello, %zone!','Let us see what %zone has to offer.','I always get lost in %zone.','-1'),
(@CHATTER_TEXTS_START+19,'Oh no, %target!','%target, are you all right?! ...No, clearly not.','Rest easy, %target. The spirit healer will patch you up.','That looked painful, %target.','Someone help %target!','Too late... Sorry, %target.','Ouch. Hang in there, %target.','%target fell! Careful, everyone!','-1'),
(@CHATTER_TEXTS_START+20,'Congratulations on level %target_level, %target!','Ding! Well done, %target!','Level %target_level already? Impressive, %target.','Look at you, %target. Getting stronger every day.','Grats, %target!','Another level for %target! Drinks are on you.','Well earned, %target.','%target, you will outlevel me soon.','-1'),
(@CHATTER_TEXTS_START+21,'Good morning, everyone!','What a fresh morning in %zone.','Early bird catches the loot.','I need breakfast. And coffee. Mostly coffee.','The sun is up, let us get moving.','Did anyone else sleep on a rock last night?','Morning! Any plans for today?','A new day, new adventures.','-1'),
(@CHATTER_TEXTS_START+22,'Getting late. Time to find an inn soon.','Beautiful sunset over %zone.','One more fight, then I call it a day.','Evening, everyone.','The monsters get bolder when it gets dark.','Anyone up for a drink tonight?','Long day. My feet agree.','The evening air in %zone is nice.','-1'),
(@CHATTER_TEXTS_START+23,'Why am I still awake?','Quiet night in %zone.','Can barely see where I am going.','The stars are bright tonight.','Night shift, again.','Something is moving out there in the dark...','Anyone else can not sleep?','Everything sounds scarier at night.','-1'),
(@CHATTER_TEXTS_START+24,'Great, rain. Just great.','My boots are full of water.','Rain in %zone again...','At least the rain washes off the blood.','Anyone got a spare cloak? A dry one?','I love the smell of rain.','The murlocs must love this weather.','Soaked to the bone.','-1'),
(@CHATTER_TEXTS_START+25,'Brr, it is freezing!','Snow! Anyone up for a snowball fight?','I can not feel my toes anymore.','Everything is so quiet when it snows.','I should have packed warmer clothes.','Snow in %zone. Beautiful and cold.','My beard is frozen. And I do not even have a beard.','Hot soup. I need hot soup.','-1'),
(@CHATTER_TEXTS_START+26,'What a storm!','I can barely see my own hand.','Take cover, this storm is getting worse!','Sand in my armor. Everywhere.','The sky is angry today.','Did that thunder just shake the ground?','Not the best weather for traveling.','Hold on to your hats!','-1'),
(@CHATTER_TEXTS_START+27,'What a wonderful day!','I feel like I could take on a dragon today!','Life is good.','Anyone want to hear a joke? No? Too bad, I am in a great mood anyway.','Hehe, everything is going my way.','Smile, everyone!','%zone is lovely today, is it not?','I love being an adventurer.','-1'),
(@CHATTER_TEXTS_START+28,'Everything is going wrong today.','Leave me alone.','Why does everything in %zone want to bite me?','Worst. Day. Ever.','Do not talk to me before I had a drink.','Hmpf.','I should have stayed in bed.','Somebody is going to pay for this.','-1'),
(@CHATTER_TEXTS_START+29,'*yawn*','I could use a nap.','My legs feel like lead.','How far is the next inn?','Just five more minutes...','I have been walking for hours.','Need... rest...','I am too old for this.','-1'),
(@CHATTER_TEXTS_START+30,'Hey %target, I am on "%quest" too. Want to team up? I sent you an invite.','%target, "%quest" is too much for one. Shall we do it together?','I saw you are working on "%quest". Join my group and we get it done!','Looking for help with "%quest" as well? Accept my invite!',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+31,'Anyone up for %dungeon? We still have room!','LFM %dungeon, all roles welcome!','Heading to %dungeon soon. Who wants to come along?','Group for %dungeon forming, whisper me!',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+32,'%target, we are going to %dungeon. Coming along? Accept my invite!','Hey %target, we need one more for %dungeon. Interested?','%dungeon, you and me and a few friends. What do you say, %target?',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+33,'I need those for "%quest" too!','Hey, I am after %enemy as well. Let me help!','"%quest"? Same here! Let us take them down together.','Need a hand with %enemy? I am on it!',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+34,'Shall we team up until we are done with "%quest"?','We are faster together. Group up for "%quest"?','Want to share the kills for "%quest"? I sent you an invite.',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+35,'We are gathering against %boss in %place! Who is in?','%boss has been seen in %place. Raid forming, join us!','Time to put %boss in %place in its place. Need fighters!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+36,'%target, we are taking on %boss in %place. Join our raid!','Hey %target, fancy fighting %boss? We have a raid ready in %place.','%boss in %place, tonight. Are you with us, %target?',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+37,'Forming a raid for %raid. Need strong fighters!','LFM %raid, tanks and healers especially welcome!','Who wants loot from %raid? Join our raid!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+38,'%target, want to join our raid to %raid? Accept the invite and we will meet you.','Hey %target, we are going to %raid and have a spot left for you.','%raid needs heroes, %target. Coming?',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+39,'Great, let us go!','Welcome aboard, %target!','Excellent. Lead the way!','Perfect, the others are on their way.',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+40,'Too bad. Maybe next time.','No worries, good luck out there!','Alright, I will ask someone else.',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+41,'That is done. Thanks for the help, %target! Good luck.','We did it! I will be on my way now. Take care, %target.','Good work, everyone. Farewell!','A pleasure fighting with you, %target. Until next time!',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+42,'I have to go now. Farewell, %target!','Sorry, duty calls. Good luck!','That took long enough, I am heading off. Take care!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+43,'We are raiding the %enemy camp over there! Who is with us?','Those %enemy have caused enough trouble. Gather at my side!','To arms! We clear out the %enemy camp!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+44,'Attacking the %enemy camp in %zone, join us!','Clearing out %enemy in %zone. Everyone nearby is welcome!',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+45,'%enemy has been spotted nearby! Let us hunt it down together!','Hunters, gather! %enemy is close!','I found the tracks of %enemy. Who joins the hunt?',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+46,'Hunting %enemy in %zone, anyone want to join?','%enemy spotted in %zone! Hunting party forming.',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+47,'Charge!','Now! Attack!','For glory!','Show them no mercy!',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+48,'Victory! Thanks for joining, everyone.','That is the end of %enemy. Well fought!','Done! Drinks are on me at the next inn.',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+49,'Let us call it off, this is going nowhere.','Retreat! We will try again another day.',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+50,'Count me in!','Right behind you!','Let us do this!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+51,'yes|yeah|yep|sure|ok|okay|alright|count me in|invite|inv|why not|lets go|let\'s go',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+52,'no|nope|no thanks|not now|maybe later|later',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+53,'Sorry, plans changed.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+54,'Hey %target! Good to see you again!','%target! Over here!','Look who it is! Hello, %target!','%target, my friend! How have you been?','Ah, %target. Always a pleasure.',NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+55,'Oh. It is you, %target.','Not you again.','Keep walking, %target.','I remember you, %target. And not fondly.','Hmpf. %target.',NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+56,'%target! My old friend!','Well, if it is not %target! How are you?','%target! It has been too long.','Good to see you in one piece, %target.',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+57,'Mind if I join you for a while, %target?','Let us travel together for a while, %target.','Wait for me, %target, I am coming along!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+58,'You again, %target?','Get out of my way, %target.','Still alive, %target? Pity.','%target. I was hoping I would not run into you.',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+59,'Mind your own business, %target.','Big words from you, %target.','Say that again and see what happens, %target.','I do not have time for you, %target.',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+60,'Has anyone seen %rival? Still owes me ten gold.','If you meet %rival, do not trust a word.','%rival could not hit a training dummy.','Funny how %rival always shows up after the fight is over.',NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+61,'I will go my own way now. See you, friend!','That was a nice trip. Take care!','Our paths part here. Farewell!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+62,'WTS %item for %price, whisper me "buy"!','Selling %item, %price. Whisper me!','%item for just %price, first come first served!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+63,'WTB %count x %item, paying %price each. Whisper me "sell"!','Looking for %count x %item, %price each.','Anyone got %count x %item? Paying %price each.',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+64,'Pleasure doing business! %item is yours.','Deal! Enjoy your %item.',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+65,'Thanks! Here are %price for the goods.','Perfect, exactly what I needed. %price for you.',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+66,'That is not enough gold, friend.','Come back when you can afford it.',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
