(@CHATTER_TEXTS_START+73,'More of them are coming!','Another wave! Hold the line!','They keep coming! Stand fast!',NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+74,'%town is safe! Thank you, defenders!','We drove them back! Well fought, everyone!',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
(@CHATTER_TEXTS_START+75,'We could not hold them... They are pulling back for now.','Fall back! We will rebuild %town.',NULL,NULL,NULL,NULL,NULL,NULL,'-1'),
